const variants = (
  prefix: string,
  color: string,
  colorHex: string,
  sizes: Array<[string, boolean, number?]>,
) =>
  sizes.map(([label, available, quantity], index) => ({
    id: `${prefix}-${index + 1}`,
    label,
    color,
    colorHex,
    available,
    quantity,
  }));

